tool_use_result.content:
/* ClipCast Design System */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --primary: #6366f1;
  --primary-dark: #4f46e5;
  --primary-light: #818cf8;
  --accent: #ff613d;
  --accent-dark: #f43f5e;
  --dark: #292a2e;
  --gray-900: #1f2937;
  --gray-800: #374151;
  --gray-600: #4b5563;
  --gray-400: #9ca3af;
  --gray-200: #e5e7eb;
  --gray-100: #f3f4f6;
  --gray-50: #f9fafb;
  --white: #ffffff;
  --gradient-primary: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  --gradient-accent: linear-gradient(135deg, var(--accent) 0%, var(--accent-dark) 100%);
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
  --shadow-xl: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --transition: all 0.2s ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--dark);
  background: var(--white);
  -webkit-font-smoothing: antialiased;
}

a {
  text-decoration: none;
  color: inherit;
  transition: var(--transition);
}

img {
  max-width: 100%;
  height: auto;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.2;
  color: var(--dark);
}

h1 { font-size: 3.5rem; font-weight: 800; }
h2 { font-size: 2.5rem; }
h3 { font-size: 1.5rem; }
h4 { font-size: 1.25rem; }

.text-gradient {
  background: var(--gradient-primary);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Container */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.container-sm {
  max-width: 800px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  transition: var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--gradient-primary);
  color: var(--white);
  box-shadow: 0 4px 14px 0 rgb(99 102 241 / 0.4);
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px 0 rgb(99 102 241 / 0.5);
}

.btn-secondary {
  background: var(--white);
  color: var(--dark);
  border: 1px solid var(--gray-200);
}

.btn-secondary:hover {
  background: var(--gray-50);
  border-color: var(--gray-400);
}

.btn-accent {
  background: var(--gradient-accent);
  color: var(--white);
  box-shadow: 0 4px 14px 0 rgb(255 95 61 / 0.4);
}

.btn-accent:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px 0 rgb(255 95 61 / 0.5);
}

.btn-lg {
  padding: 16px 32px;
  font-size: 1.125rem;
}

.btn-sm {
  padding: 8px 16px;
  font-size: 0.875rem;
}

/* Navigation */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--gray-100);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
}

.nav-logo svg {
  width: 36px;
  height: 36px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-link {
  font-weight: 500;
  color: var(--gray-600);
}

.nav-link:hover {
  color: var(--primary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

/* Hero */
.hero {
  padding: 160px 0 80px;
  text-align: center;
  background: linear-gradient(180deg, var(--gray-50) 0%, var(--white) 100%);
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: var(--primary);
  color: var(--white);
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  margin-bottom: 24px;
}

.hero h1 {
  max-width: 800px;
  margin: 0 auto 24px;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--gray-600);
  max-width: 600px;
  margin: 0 auto 40px;
}

.hero-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

.hero-note {
  margin-top: 24px;
  font-size: 0.875rem;
  color: var(--gray-400);
}

/* Logo Bar */
.logo-bar {
  padding: 48px 0;
  background: var(--white);
  border-top: 1px solid var(--gray-100);
  border-bottom: 1px solid var(--gray-100);
}

.logo-bar-inner {
  text-align: center;
}

.logo-bar-title {
  font-size: 0.875rem;
  color: var(--gray-400);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 24px;
}

.logo-bar-logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 48px;
  flex-wrap: wrap;
  opacity: 0.6;
}

.logo-bar-logos span {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--gray-600);
}

/* Section Styles */
.section {
  padding: 80px 0;
}

.section-gray {
  background: var(--gray-50);
}

.section-dark {
  background: var(--gray-900);
  color: var(--white);
}

.section-dark h2,
.section-dark h3,
.section-dark h4 {
  color: var(--white);
}

.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 56px;
}

.section-header h2 {
  margin-bottom: 16px;
}

.section-header p {
  color: var(--gray-600);
  font-size: 1.125rem;
}

/* Feature Cards */
.feature-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
}

.feature-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--gray-100);
  transition: var(--transition);
}

.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.feature-icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  font-size: 1.5rem;
}

.feature-icon-primary {
  background: linear-gradient(135deg, var(--primary-light) 0%, var(--primary) 100%);
  color: var(--white);
}

.feature-icon-accent {
  background: linear-gradient(135deg, #fda4af 0%, var(--accent) 100%);
  color: var(--white);
}

.feature-card h3 {
  margin-bottom: 12px;
}

.feature-card p {
  color: var(--gray-600);
  line-height: 1.7;
}

/* Highlight Feature */
.highlight-feature {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.highlight-feature.reverse {
  direction: rtl;
}

.highlight-feature.reverse > * {
  direction: ltr;
}

.highlight-content h2 {
  margin-bottom: 24px;
}

.highlight-content p {
  color: var(--gray-600);
  margin-bottom: 24px;
  font-size: 1.125rem;
  line-height: 1.8;
}

.highlight-visual {
  background: var(--gray-100);
  border-radius: var(--radius-xl);
  overflow: hidden;
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Use Cases */
.use-case-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.use-case-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  text-align: center;
  border: 1px solid var(--gray-100);
  transition: var(--transition);
  cursor: pointer;
}

.use-case-card:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-lg);
}

.use-case-icon {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-full);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  font-size: 1.75rem;
}

.use-case-card h4 {
  margin-bottom: 8px;
}

.use-case-card p {
  color: var(--gray-600);
  font-size: 0.875rem;
}

/* Stats */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 48px;
  text-align: center;
}

.stat-item h3 {
  font-size: 3rem;
  font-weight: 800;
  background: var(--gradient-primary);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 8px;
}

.stat-item p {
  color: var(--gray-400);
  font-size: 1rem;
}

/* Testimonials */
.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
  gap: 32px;
}

.testimonial-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--gray-100);
}

.testimonial-quote {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--gray-800);
  margin-bottom: 24px;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 16px;
}

.testimonial-avatar {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  background: var(--gradient-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-weight: 700;
}

.testimonial-info h4 {
  font-size: 1rem;
  margin-bottom: 2px;
}

.testimonial-info p {
  color: var(--gray-400);
  font-size: 0.875rem;
}

/* CTA Banner */
.cta-banner {
  padding: 80px 0;
  background: var(--gradient-primary);
  text-align: center;
  color: var(--white);
}

.cta-banner h2 {
  color: var(--white);
  margin-bottom: 16px;
}

.cta-banner p {
  opacity: 0.9;
  margin-bottom: 32px;
  font-size: 1.125rem;
}

/* Pricing */
.pricing-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  margin-bottom: 48px;
}

.billing-toggle {
  display: flex;
  align-items: center;
  gap: 12px;
}

.billing-toggle span {
  font-weight: 500;
  color: var(--gray-600);
}

.billing-toggle span.active {
  color: var(--dark);
}

.toggle-switch {
  width: 56px;
  height: 28px;
  background: var(--gray-200);
  border-radius: var(--radius-full);
  position: relative;
  cursor: pointer;
  transition: var(--transition);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 4px;
  left: 4px;
  width: 20px;
  height: 20px;
  background: var(--white);
  border-radius: var(--radius-full);
  transition: var(--transition);
  box-shadow: var(--shadow-sm);
}

.toggle-switch.active {
  background: var(--primary);
}

.toggle-switch.active::after {
  left: 32px;
}

.save-badge {
  background: var(--accent);
  color: var(--white);
  padding: 4px 12px;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
}

.team-size-slider {
  max-width: 300px;
  margin: 0 auto;
}

.team-size-slider label {
  display: block;
  font-weight: 500;
  margin-bottom: 12px;
  text-align: center;
}

.team-size-slider input[type="range"] {
  width: 100%;
  height: 8px;
  border-radius: var(--radius-full);
  background: var(--gray-200);
  outline: none;
  -webkit-appearance: none;
}

.team-size-slider input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 24px;
  height: 24px;
  border-radius: var(--radius-full);
  background: var(--primary);
  cursor: pointer;
  box-shadow: var(--shadow-md);
}

.team-size-value {
  text-align: center;
  font-weight: 700;
  color: var(--primary);
  font-size: 1.25rem;
  margin-top: 8px;
}

/* Pricing Cards */
.pricing-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-bottom: 64px;
}

.pricing-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: 32px;
  border: 2px solid var(--gray-100);
  position: relative;
  transition: var(--transition);
}

.pricing-card:hover {
  border-color: var(--primary);
}

.pricing-card.featured {
  border-color: var(--primary);
  box-shadow: var(--shadow-xl);
  transform: scale(1.05);
}

.pricing-card-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--gradient-primary);
  color: var(--white);
  padding: 4px 16px;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.pricing-card h3 {
  font-size: 1.25rem;
  margin-bottom: 8px;
}

.pricing-card-price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--dark);
  margin-bottom: 8px;
}

.pricing-card-price span {
  font-size: 1rem;
  font-weight: 500;
  color: var(--gray-400);
}

.pricing-card-desc {
  color: var(--gray-600);
  font-size: 0.875rem;
  margin-bottom: 24px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--gray-100);
}

.pricing-features {
  list-style: none;
  margin-bottom: 24px;
}

.pricing-features li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 8px 0;
  font-size: 0.9rem;
  color: var(--gray-700);
}

.pricing-features li svg {
  flex-shrink: 0;
  color: var(--primary);
  margin-top: 2px;
}

/* Comparison Table */
.comparison-table-wrapper {
  overflow-x: auto;
  margin-bottom: 48px;
}

.comparison-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 800px;
}

.comparison-table th,
.comparison-table td {
  padding: 16px 20px;
  text-align: center;
  border-bottom: 1px solid var(--gray-100);
}

.comparison-table th {
  background: var(--gray-50);
  font-weight: 600;
  font-size: 0.9rem;
}

.comparison-table th:first-child,
.comparison-table td:first-child {
  text-align: left;
  font-weight: 500;
}

.comparison-table .check {
  color: var(--primary);
}

.comparison-table .dash {
  color: var(--gray-300);
}

.comparison-table .featured-col {
  background: rgba(99, 102, 241, 0.05);
}

/* FAQ Accordion */
.faq-list {
  max-width: 700px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-100);
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 0;
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  transition: var(--transition);
}

.faq-question:hover {
  color: var(--primary);
}

.faq-question svg {
  transition: var(--transition);
}

.faq-item.open .faq-question svg {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-item.open .faq-answer {
  max-height: 500px;
}

.faq-answer p {
  padding-bottom: 20px;
  color: var(--gray-600);
  line-height: 1.7;
}

/* Forms */
.form-card {
  max-width: 420px;
  margin: 0 auto;
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: 48px;
  box-shadow: var(--shadow-xl);
}

.form-card h2 {
  text-align: center;
  margin-bottom: 8px;
}

.form-card-subtitle {
  text-align: center;
  color: var(--gray-600);
  margin-bottom: 32px;
}

.social-buttons {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 12px 20px;
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  background: var(--white);
  font-weight: 500;
  cursor: pointer;
  transition: var(--transition);
}

.social-btn:hover {
  background: var(--gray-50);
  border-color: var(--gray-400);
}

.social-btn svg {
  width: 20px;
  height: 20px;
}

.divider {
  display: flex;
  align-items: center;
  gap: 16px;
  margin: 24px 0;
  color: var(--gray-400);
  font-size: 0.875rem;
}

.divider::before,
.divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--gray-200);
}

.form-group {
  margin-bottom: 16px;
}

.form-group label {
  display: block;
  font-weight: 500;
  margin-bottom: 6px;
  font-size: 0.9rem;
}

.form-group input {
  width: 100%;
  padding: 12px 16px;
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  font-size: 1rem;
  transition: var(--transition);
}

.form-group input:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.1);
}

.form-footer {
  text-align: center;
  font-size: 0.875rem;
  color: var(--gray-600);
  margin-top: 24px;
}

.form-footer a {
  color: var(--primary);
  font-weight: 500;
}

/* Blog Cards */
.blog-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
}

.blog-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--gray-100);
  transition: var(--transition);
}

.blog-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.blog-card-image {
  height: 200px;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400);
}

.blog-card-content {
  padding: 24px;
}

.blog-card-content h4 {
  margin-bottom: 8px;
  transition: var(--transition);
}

.blog-card:hover h4 {
  color: var(--primary);
}

.blog-card-content p {
  color: var(--gray-600);
  font-size: 0.9rem;
}

/* Footer */
.footer {
  background: var(--gray-900);
  color: var(--gray-400);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand {
  max-width: 280px;
}

.footer-brand .nav-logo {
  color: var(--white);
  margin-bottom: 16px;
}

.footer-brand p {
  font-size: 0.9rem;
  line-height: 1.7;
}

.footer-col h4 {
  color: var(--white);
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 20px;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 12px;
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  padding-top: 32px;
  border-top: 1px solid var(--gray-800);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.875rem;
}

.footer-legal {
  display: flex;
  gap: 24px;
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--white);
  border-top: 1px solid var(--gray-200);
  padding: 24px;
  z-index: 2000;
  box-shadow: 0 -4px 20px rgba(0,0,0,0.1);
  display: none;
}

.cookie-banner.show {
  display: block;
}

.cookie-banner-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.cookie-banner p {
  font-size: 0.9rem;
  color: var(--gray-700);
}

.cookie-banner-actions {
  display: flex;
  gap: 12px;
}

/* Modal */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: 3000;
  display: none;
  align-items: center;
  justify-content: center;
}

.modal-overlay.show {
  display: flex;
}

.modal {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: 32px;
  max-width: 500px;
  width: 90%;
  max-height: 90vh;
  overflow-y: auto;
}

.modal h3 {
  margin-bottom: 24px;
}

.modal-close {
  float: right;
  background: none;
  border: none;
  font-size: 1.5rem;
  cursor: pointer;
  color: var(--gray-400);
}

.cookie-category {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
  border-bottom: 1px solid var(--gray-100);
}

.cookie-category-info h4 {
  font-size: 0.95rem;
  margin-bottom: 4px;
}

.cookie-category-info p {
  font-size: 0.8rem;
  color: var(--gray-600);
}

.toggle-checkbox {
  width: 48px;
  height: 26px;
  background: var(--gray-200);
  border-radius: var(--radius-full);
  position: relative;
  cursor: pointer;
  transition: var(--transition);
}

.toggle-checkbox::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 20px;
  height: 20px;
  background: var(--white);
  border-radius: var(--radius-full);
  transition: var(--transition);
}

.toggle-checkbox.active {
  background: var(--primary);
}

.toggle-checkbox.active::after {
  left: 25px;
}

/* Integrations */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}

.integration-item {
  aspect-ratio: 1;
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  transition: var(--transition);
  cursor: pointer;
}

.integration-item:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-md);
}

/* Responsive */
@media (max-width: 1024px) {
  h1 { font-size: 2.5rem; }
  h2 { font-size: 2rem; }

  .use-case-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .pricing-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .pricing-card.featured {
    transform: none;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .hero {
    padding: 120px 0 60px;
  }

  .highlight-feature {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .highlight-feature.reverse {
    direction: ltr;
  }

  .stats-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .pricing-cards {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 16px;
    text-align: center;
  }

  .cookie-banner-inner {
    flex-direction: column;
    text-align: center;
  }

  .blog-grid {
    grid-template-columns: 1fr;
  }
}

/* ClipCast Design System */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --primary: #6366f1;
  --primary-dark: #4f46e5;
  --primary-light: #818cf8;
  --accent: #ff613d;
  --accent-dark: #f43f5e;
  --dark: #292a2e;
  --gray-900: #1f2937;
  --gray-800: #374151;
  --gray-600: #4b5563;
  --gray-400: #9ca3af;
  --gray-200: #e5e7eb;
  --gray-100: #f3f4f6;
  --gray-50: #f9fafb;
  --white: #ffffff;
  --gradient-primary: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  --gradient-accent: linear-gradient(135deg, var(--accent) 0%, var(--accent-dark) 100%);
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
  --shadow-xl: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --transition: all 0.2s ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--dark);
  background: var(--white);
  -webkit-font-smoothing: antialiased;
}

a {
  text-decoration: none;
  color: inherit;
  transition: var(--transition);
}

img {
  max-width: 100%;
  height: auto;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.2;
  color: var(--dark);
}

h1 { font-size: 3.5rem; font-weight: 800; }
h2 { font-size: 2.5rem; }
h3 { font-size: 1.5rem; }
h4 { font-size: 1.25rem; }

.text-gradient {
  background: var(--gradient-primary);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Container */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.container-sm {
  max-width: 800px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  transition: var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--gradient-primary);
  color: var(--white);
  box-shadow: 0 4px 14px 0 rgb(99 102 241 / 0.4);
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px 0 rgb(99 102 241 / 0.5);
}

.btn-secondary {
  background: var(--white);
  color: var(--dark);
  border: 1px solid var(--gray-200);
}

.btn-secondary:hover {
  background: var(--gray-50);
  border-color: var(--gray-400);
}

.btn-accent {
  background: var(--gradient-accent);
  color: var(--white);
  box-shadow: 0 4px 14px 0 rgb(255 95 61 / 0.4);
}

.btn-accent:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px 0 rgb(255 95 61 / 0.5);
}

.btn-lg {
  padding: 16px 32px;
  font-size: 1.125rem;
}

.btn-sm {
  padding: 8px 16px;
  font-size: 0.875rem;
}

/* Navigation */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--gray-100);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
}

.nav-logo svg {
  width: 36px;
  height: 36px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-link {
  font-weight: 500;
  color: var(--gray-600);
}

.nav-link:hover {
  color: var(--primary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

/* Hero */
.hero {
  padding: 160px 0 80px;
  text-align: center;
  background: linear-gradient(180deg, var(--gray-50) 0%, var(--white) 100%);
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: var(--primary);
  color: var(--white);
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  margin-bottom: 24px;
}

.hero h1 {
  max-width: 800px;
  margin: 0 auto 24px;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--gray-600);
  max-width: 600px;
  margin: 0 auto 40px;
}

.hero-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

.hero-note {
  margin-top: 24px;
  font-size: 0.875rem;
  color: var(--gray-400);
}

/* Logo Bar */
.logo-bar {
  padding: 48px 0;
  background: var(--white);
  border-top: 1px solid var(--gray-100);
  border-bottom: 1px solid var(--gray-100);
}

.logo-bar-inner {
  text-align: center;
}

.logo-bar-title {
  font-size: 0.875rem;
  color: var(--gray-400);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 24px;
}

.logo-bar-logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 48px;
  flex-wrap: wrap;
  opacity: 0.6;
}

.logo-bar-logos span {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--gray-600);
}

/* Section Styles */
.section {
  padding: 80px 0;
}

.section-gray {
  background: var(--gray-50);
}

.section-dark {
  background: var(--gray-900);
  color: var(--white);
}

.section-dark h2,
.section-dark h3,
.section-dark h4 {
  color: var(--white);
}

.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 56px;
}

.section-header h2 {
  margin-bottom: 16px;
}

.section-header p {
  color: var(--gray-600);
  font-size: 1.125rem;
}

/* Feature Cards */
.feature-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
}

.feature-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--gray-100);
  transition: var(--transition);
}

.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.feature-icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  font-size: 1.5rem;
}

.feature-icon-primary {
  background: linear-gradient(135deg, var(--primary-light) 0%, var(--primary) 100%);
  color: var(--white);
}

.feature-icon-accent {
  background: linear-gradient(135deg, #fda4af 0%, var(--accent) 100%);
  color: var(--white);
}

.feature-card h3 {
  margin-bottom: 12px;
}

.feature-card p {
  color: var(--gray-600);
  line-height: 1.7;
}

/* Highlight Feature */
.highlight-feature {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.highlight-feature.reverse {
  direction: rtl;
}

.highlight-feature.reverse > * {
  direction: ltr;
}

.highlight-content h2 {
  margin-bottom: 24px;
}

.highlight-content p {
  color: var(--gray-600);
  margin-bottom: 24px;
  font-size: 1.125rem;
  line-height: 1.8;
}

.highlight-visual {
  background: var(--gray-100);
  border-radius: var(--radius-xl);
  overflow: hidden;
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Use Cases */
.use-case-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.use-case-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  text-align: center;
  border: 1px solid var(--gray-100);
  transition: var(--transition);
  cursor: pointer;
}

.use-case-card:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-lg);
}

.use-case-icon {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-full);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  font-size: 1.75rem;
}

.use-case-card h4 {
  margin-bottom: 8px;
}

.use-case-card p {
  color: var(--gray-600);
  font-size: 0.875rem;
}

/* Stats */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 48px;
  text-align: center;
}

.stat-item h3 {
  font-size: 3rem;
  font-weight: 800;
  background: var(--gradient-primary);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 8px;
}

.stat-item p {
  color: var(--gray-400);
  font-size: 1rem;
}

/* Testimonials */
.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
  gap: 32px;
}

.testimonial-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--gray-100);
}

.testimonial-quote {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--gray-800);
  margin-bottom: 24px;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 16px;
}

.testimonial-avatar {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  background: var(--gradient-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-weight: 700;
}

.testimonial-info h4 {
  font-size: 1rem;
  margin-bottom: 2px;
}

.testimonial-info p {
  color: var(--gray-400);
  font-size: 0.875rem;
}

/* CTA Banner */
.cta-banner {
  padding: 80px 0;
  background: var(--gradient-primary);
  text-align: center;
  color: var(--white);
}

.cta-banner h2 {
  color: var(--white);
  margin-bottom: 16px;
}

.cta-banner p {
  opacity: 0.9;
  margin-bottom: 32px;
  font-size: 1.125rem;
}

/* Pricing */
.pricing-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  margin-bottom: 48px;
}

.billing-toggle {
  display: flex;
  align-items: center;
  gap: 12px;
}

.billing-toggle span {
  font-weight: 500;
  color: var(--gray-600);
}

.billing-toggle span.active {
  color: var(--dark);
}

.toggle-switch {
  width: 56px;
  height: 28px;
  background: var(--gray-200);
  border-radius: var(--radius-full);
  position: relative;
  cursor: pointer;
  transition: var(--transition);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 4px;
  left: 4px;
  width: 20px;
  height: 20px;
  background: var(--white);
  border-radius: var(--radius-full);
  transition: var(--transition);
  box-shadow: var(--shadow-sm);
}

.toggle-switch.active {
  background: var(--primary);
}

.toggle-switch.active::after {
  left: 32px;
}

.save-badge {
  background: var(--accent);
  color: var(--white);
  padding: 4px 12px;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
}

.team-size-slider {
  max-width: 300px;
  margin: 0 auto;
}

.team-size-slider label {
  display: block;
  font-weight: 500;
  margin-bottom: 12px;
  text-align: center;
}

.team-size-slider input[type="range"] {
  width: 100%;
  height: 8px;
  border-radius: var(--radius-full);
  background: var(--gray-200);
  outline: none;
  -webkit-appearance: none;
}

.team-size-slider input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 24px;
  height: 24px;
  border-radius: var(--radius-full);
  background: var(--primary);
  cursor: pointer;
  box-shadow: var(--shadow-md);
}

.team-size-value {
  text-align: center;
  font-weight: 700;
  color: var(--primary);
  font-size: 1.25rem;
  margin-top: 8px;
}

/* Pricing Cards */
.pricing-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-bottom: 64px;
}

.pricing-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: 32px;
  border: 2px solid var(--gray-100);
  position: relative;
  transition: var(--transition);
}

.pricing-card:hover {
  border-color: var(--primary);
}

.pricing-card.featured {
  border-color: var(--primary);
  box-shadow: var(--shadow-xl);
  transform: scale(1.05);
}

.pricing-card-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--gradient-primary);
  color: var(--white);
  padding: 4px 16px;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.pricing-card h3 {
  font-size: 1.25rem;
  margin-bottom: 8px;
}

.pricing-card-price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--dark);
  margin-bottom: 8px;
}

.pricing-card-price span {
  font-size: 1rem;
  font-weight: 500;
  color: var(--gray-400);
}

.pricing-card-desc {
  color: var(--gray-600);
  font-size: 0.875rem;
  margin-bottom: 24px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--gray-100);
}

.pricing-features {
  list-style: none;
  margin-bottom: 24px;
}

.pricing-features li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 8px 0;
  font-size: 0.9rem;
  color: var(--gray-700);
}

.pricing-features li svg {
  flex-shrink: 0;
  color: var(--primary);
  margin-top: 2px;
}

/* Comparison Table */
.comparison-table-wrapper {
  overflow-x: auto;
  margin-bottom: 48px;
}

.comparison-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 800px;
}

.comparison-table th,
.comparison-table td {
  padding: 16px 20px;
  text-align: center;
  border-bottom: 1px solid var(--gray-100);
}

.comparison-table th {
  background: var(--gray-50);
  font-weight: 600;
  font-size: 0.9rem;
}

.comparison-table th:first-child,
.comparison-table td:first-child {
  text-align: left;
  font-weight: 500;
}

.comparison-table .check {
  color: var(--primary);
}

.comparison-table .dash {
  color: var(--gray-300);
}

.comparison-table .featured-col {
  background: rgba(99, 102, 241, 0.05);
}

/* FAQ Accordion */
.faq-list {
  max-width: 700px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-100);
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 0;
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  transition: var(--transition);
}

.faq-question:hover {
  color: var(--primary);
}

.faq-question svg {
  transition: var(--transition);
}

.faq-item.open .faq-question svg {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-item.open .faq-answer {
  max-height: 500px;
}

.faq-answer p {
  padding-bottom: 20px;
  color: var(--gray-600);
  line-height: 1.7;
}

/* Forms */
.form-card {
  max-width: 420px;
  margin: 0 auto;
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: 48px;
  box-shadow: var(--shadow-xl);
}

.form-card h2 {
  text-align: center;
  margin-bottom: 8px;
}

.form-card-subtitle {
  text-align: center;
  color: var(--gray-600);
  margin-bottom: 32px;
}

.social-buttons {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 12px 20px;
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  background: var(--white);
  font-weight: 500;
  cursor: pointer;
  transition: var(--transition);
}

.social-btn:hover {
  background: var(--gray-50);
  border-color: var(--gray-400);
}

.social-btn svg {
  width: 20px;
  height: 20px;
}

.divider {
  display: flex;
  align-items: center;
  gap: 16px;
  margin: 24px 0;
  color: var(--gray-400);
  font-size: 0.875rem;
}

.divider::before,
.divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--gray-200);
}

.form-group {
  margin-bottom: 16px;
}

.form-group label {
  display: block;
  font-weight: 500;
  margin-bottom: 6px;
  font-size: 0.9rem;
}

.form-group input {
  width: 100%;
  padding: 12px 16px;
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  font-size: 1rem;
  transition: var(--transition);
}

.form-group input:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.1);
}

.form-footer {
  text-align: center;
  font-size: 0.875rem;
  color: var(--gray-600);
  margin-top: 24px;
}

.form-footer a {
  color: var(--primary);
  font-weight: 500;
}

/* Blog Cards */
.blog-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
}

.blog-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--gray-100);
  transition: var(--transition);
}

.blog-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.blog-card-image {
  height: 200px;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400);
}

.blog-card-content {
  padding: 24px;
}

.blog-card-content h4 {
  margin-bottom: 8px;
  transition: var(--transition);
}

.blog-card:hover h4 {
  color: var(--primary);
}

.blog-card-content p {
  color: var(--gray-600);
  font-size: 0.9rem;
}

/* Footer */
.footer {
  background: var(--gray-900);
  color: var(--gray-400);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand {
  max-width: 280px;
}

.footer-brand .nav-logo {
  color: var(--white);
  margin-bottom: 16px;
}

.footer-brand p {
  font-size: 0.9rem;
  line-height: 1.7;
}

.footer-col h4 {
  color: var(--white);
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 20px;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 12px;
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  padding-top: 32px;
  border-top: 1px solid var(--gray-800);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.875rem;
}

.footer-legal {
  display: flex;
  gap: 24px;
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--white);
  border-top: 1px solid var(--gray-200);
  padding: 24px;
  z-index: 2000;
  box-shadow: 0 -4px 20px rgba(0,0,0,0.1);
  display: none;
}

.cookie-banner.show {
  display: block;
}

.cookie-banner-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.cookie-banner p {
  font-size: 0.9rem;
  color: var(--gray-700);
}

.cookie-banner-actions {
  display: flex;
  gap: 12px;
}

/* Modal */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: 3000;
  display: none;
  align-items: center;
  justify-content: center;
}

.modal-overlay.show {
  display: flex;
}

.modal {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: 32px;
  max-width: 500px;
  width: 90%;
  max-height: 90vh;
  overflow-y: auto;
}

.modal h3 {
  margin-bottom: 24px;
}

.modal-close {
  float: right;
  background: none;
  border: none;
  font-size: 1.5rem;
  cursor: pointer;
  color: var(--gray-400);
}

.cookie-category {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
  border-bottom: 1px solid var(--gray-100);
}

.cookie-category-info h4 {
  font-size: 0.95rem;
  margin-bottom: 4px;
}

.cookie-category-info p {
  font-size: 0.8rem;
  color: var(--gray-600);
}

.toggle-checkbox {
  width: 48px;
  height: 26px;
  background: var(--gray-200);
  border-radius: var(--radius-full);
  position: relative;
  cursor: pointer;
  transition: var(--transition);
}

.toggle-checkbox::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 20px;
  height: 20px;
  background: var(--white);
  border-radius: var(--radius-full);
  transition: var(--transition);
}

.toggle-checkbox.active {
  background: var(--primary);
}

.toggle-checkbox.active::after {
  left: 25px;
}

/* Integrations */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}

.integration-item {
  aspect-ratio: 1;
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  transition: var(--transition);
  cursor: pointer;
}

.integration-item:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-md);
}

/* Responsive */
@media (max-width: 1024px) {
  h1 { font-size: 2.5rem; }
  h2 { font-size: 2rem; }

  .use-case-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .pricing-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .pricing-card.featured {
    transform: none;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .hero {
    padding: 120px 0 60px;
  }

  .highlight-feature {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .highlight-feature.reverse {
    direction: ltr;
  }

  .stats-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .pricing-cards {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 16px;
    text-align: center;
  }

  .cookie-banner-inner {
    flex-direction: column;
    text-align: center;
  }

  .blog-grid {
    grid-template-columns: 1fr;
  }
}

raw_arguments.content:
/* ClipCast Design System */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --primary: #6366f1;
  --primary-dark: #4f46e5;
  --primary-light: #818cf8;
  --accent: #ff613d;
  --accent-dark: #f43f5e;
  --dark: #292a2e;
  --gray-900: #1f2937;
  --gray-800: #374151;
  --gray-600: #4b5563;
  --gray-400: #9ca3af;
  --gray-200: #e5e7eb;
  --gray-100: #f3f4f6;
  --gray-50: #f9fafb;
  --white: #ffffff;
  --gradient-primary: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  --gradient-accent: linear-gradient(135deg, var(--accent) 0%, var(--accent-dark) 100%);
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
  --shadow-xl: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --transition: all 0.2s ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--dark);
  background: var(--white);
  -webkit-font-smoothing: antialiased;
}

a {
  text-decoration: none;
  color: inherit;
  transition: var(--transition);
}

img {
  max-width: 100%;
  height: auto;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.2;
  color: var(--dark);
}

h1 { font-size: 3.5rem; font-weight: 800; }
h2 { font-size: 2.5rem; }
h3 { font-size: 1.5rem; }
h4 { font-size: 1.25rem; }

.text-gradient {
  background: var(--gradient-primary);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Container */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.container-sm {
  max-width: 800px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  transition: var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--gradient-primary);
  color: var(--white);
  box-shadow: 0 4px 14px 0 rgb(99 102 241 / 0.4);
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px 0 rgb(99 102 241 / 0.5);
}

.btn-secondary {
  background: var(--white);
  color: var(--dark);
  border: 1px solid var(--gray-200);
}

.btn-secondary:hover {
  background: var(--gray-50);
  border-color: var(--gray-400);
}

.btn-accent {
  background: var(--gradient-accent);
  color: var(--white);
  box-shadow: 0 4px 14px 0 rgb(255 95 61 / 0.4);
}

.btn-accent:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px 0 rgb(255 95 61 / 0.5);
}

.btn-lg {
  padding: 16px 32px;
  font-size: 1.125rem;
}

.btn-sm {
  padding: 8px 16px;
  font-size: 0.875rem;
}

/* Navigation */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--gray-100);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
}

.nav-logo svg {
  width: 36px;
  height: 36px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-link {
  font-weight: 500;
  color: var(--gray-600);
}

.nav-link:hover {
  color: var(--primary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

/* Hero */
.hero {
  padding: 160px 0 80px;
  text-align: center;
  background: linear-gradient(180deg, var(--gray-50) 0%, var(--white) 100%);
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: var(--primary);
  color: var(--white);
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  margin-bottom: 24px;
}

.hero h1 {
  max-width: 800px;
  margin: 0 auto 24px;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--gray-600);
  max-width: 600px;
  margin: 0 auto 40px;
}

.hero-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

.hero-note {
  margin-top: 24px;
  font-size: 0.875rem;
  color: var(--gray-400);
}

/* Logo Bar */
.logo-bar {
  padding: 48px 0;
  background: var(--white);
  border-top: 1px solid var(--gray-100);
  border-bottom: 1px solid var(--gray-100);
}

.logo-bar-inner {
  text-align: center;
}

.logo-bar-title {
  font-size: 0.875rem;
  color: var(--gray-400);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 24px;
}

.logo-bar-logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 48px;
  flex-wrap: wrap;
  opacity: 0.6;
}

.logo-bar-logos span {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--gray-600);
}

/* Section Styles */
.section {
  padding: 80px 0;
}

.section-gray {
  background: var(--gray-50);
}

.section-dark {
  background: var(--gray-900);
  color: var(--white);
}

.section-dark h2,
.section-dark h3,
.section-dark h4 {
  color: var(--white);
}

.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 56px;
}

.section-header h2 {
  margin-bottom: 16px;
}

.section-header p {
  color: var(--gray-600);
  font-size: 1.125rem;
}

/* Feature Cards */
.feature-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
}

.feature-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--gray-100);
  transition: var(--transition);
}

.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.feature-icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  font-size: 1.5rem;
}

.feature-icon-primary {
  background: linear-gradient(135deg, var(--primary-light) 0%, var(--primary) 100%);
  color: var(--white);
}

.feature-icon-accent {
  background: linear-gradient(135deg, #fda4af 0%, var(--accent) 100%);
  color: var(--white);
}

.feature-card h3 {
  margin-bottom: 12px;
}

.feature-card p {
  color: var(--gray-600);
  line-height: 1.7;
}

/* Highlight Feature */
.highlight-feature {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.highlight-feature.reverse {
  direction: rtl;
}

.highlight-feature.reverse > * {
  direction: ltr;
}

.highlight-content h2 {
  margin-bottom: 24px;
}

.highlight-content p {
  color: var(--gray-600);
  margin-bottom: 24px;
  font-size: 1.125rem;
  line-height: 1.8;
}

.highlight-visual {
  background: var(--gray-100);
  border-radius: var(--radius-xl);
  overflow: hidden;
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Use Cases */
.use-case-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.use-case-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  text-align: center;
  border: 1px solid var(--gray-100);
  transition: var(--transition);
  cursor: pointer;
}

.use-case-card:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-lg);
}

.use-case-icon {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-full);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  font-size: 1.75rem;
}

.use-case-card h4 {
  margin-bottom: 8px;
}

.use-case-card p {
  color: var(--gray-600);
  font-size: 0.875rem;
}

/* Stats */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 48px;
  text-align: center;
}

.stat-item h3 {
  font-size: 3rem;
  font-weight: 800;
  background: var(--gradient-primary);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 8px;
}

.stat-item p {
  color: var(--gray-400);
  font-size: 1rem;
}

/* Testimonials */
.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
  gap: 32px;
}

.testimonial-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--gray-100);
}

.testimonial-quote {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--gray-800);
  margin-bottom: 24px;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 16px;
}

.testimonial-avatar {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  background: var(--gradient-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-weight: 700;
}

.testimonial-info h4 {
  font-size: 1rem;
  margin-bottom: 2px;
}

.testimonial-info p {
  color: var(--gray-400);
  font-size: 0.875rem;
}

/* CTA Banner */
.cta-banner {
  padding: 80px 0;
  background: var(--gradient-primary);
  text-align: center;
  color: var(--white);
}

.cta-banner h2 {
  color: var(--white);
  margin-bottom: 16px;
}

.cta-banner p {
  opacity: 0.9;
  margin-bottom: 32px;
  font-size: 1.125rem;
}

/* Pricing */
.pricing-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  margin-bottom: 48px;
}

.billing-toggle {
  display: flex;
  align-items: center;
  gap: 12px;
}

.billing-toggle span {
  font-weight: 500;
  color: var(--gray-600);
}

.billing-toggle span.active {
  color: var(--dark);
}

.toggle-switch {
  width: 56px;
  height: 28px;
  background: var(--gray-200);
  border-radius: var(--radius-full);
  position: relative;
  cursor: pointer;
  transition: var(--transition);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 4px;
  left: 4px;
  width: 20px;
  height: 20px;
  background: var(--white);
  border-radius: var(--radius-full);
  transition: var(--transition);
  box-shadow: var(--shadow-sm);
}

.toggle-switch.active {
  background: var(--primary);
}

.toggle-switch.active::after {
  left: 32px;
}

.save-badge {
  background: var(--accent);
  color: var(--white);
  padding: 4px 12px;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
}

.team-size-slider {
  max-width: 300px;
  margin: 0 auto;
}

.team-size-slider label {
  display: block;
  font-weight: 500;
  margin-bottom: 12px;
  text-align: center;
}

.team-size-slider input[type="range"] {
  width: 100%;
  height: 8px;
  border-radius: var(--radius-full);
  background: var(--gray-200);
  outline: none;
  -webkit-appearance: none;
}

.team-size-slider input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 24px;
  height: 24px;
  border-radius: var(--radius-full);
  background: var(--primary);
  cursor: pointer;
  box-shadow: var(--shadow-md);
}

.team-size-value {
  text-align: center;
  font-weight: 700;
  color: var(--primary);
  font-size: 1.25rem;
  margin-top: 8px;
}

/* Pricing Cards */
.pricing-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-bottom: 64px;
}

.pricing-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: 32px;
  border: 2px solid var(--gray-100);
  position: relative;
  transition: var(--transition);
}

.pricing-card:hover {
  border-color: var(--primary);
}

.pricing-card.featured {
  border-color: var(--primary);
  box-shadow: var(--shadow-xl);
  transform: scale(1.05);
}

.pricing-card-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--gradient-primary);
  color: var(--white);
  padding: 4px 16px;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
}

.pricing-card h3 {
  font-size: 1.25rem;
  margin-bottom: 8px;
}

.pricing-card-price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--dark);
  margin-bottom: 8px;
}

.pricing-card-price span {
  font-size: 1rem;
  font-weight: 500;
  color: var(--gray-400);
}

.pricing-card-desc {
  color: var(--gray-600);
  font-size: 0.875rem;
  margin-bottom: 24px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--gray-100);
}

.pricing-features {
  list-style: none;
  margin-bottom: 24px;
}

.pricing-features li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 8px 0;
  font-size: 0.9rem;
  color: var(--gray-700);
}

.pricing-features li svg {
  flex-shrink: 0;
  color: var(--primary);
  margin-top: 2px;
}

/* Comparison Table */
.comparison-table-wrapper {
  overflow-x: auto;
  margin-bottom: 48px;
}

.comparison-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 800px;
}

.comparison-table th,
.comparison-table td {
  padding: 16px 20px;
  text-align: center;
  border-bottom: 1px solid var(--gray-100);
}

.comparison-table th {
  background: var(--gray-50);
  font-weight: 600;
  font-size: 0.9rem;
}

.comparison-table th:first-child,
.comparison-table td:first-child {
  text-align: left;
  font-weight: 500;
}

.comparison-table .check {
  color: var(--primary);
}

.comparison-table .dash {
  color: var(--gray-300);
}

.comparison-table .featured-col {
  background: rgba(99, 102, 241, 0.05);
}

/* FAQ Accordion */
.faq-list {
  max-width: 700px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-100);
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 0;
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  transition: var(--transition);
}

.faq-question:hover {
  color: var(--primary);
}

.faq-question svg {
  transition: var(--transition);
}

.faq-item.open .faq-question svg {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-item.open .faq-answer {
  max-height: 500px;
}

.faq-answer p {
  padding-bottom: 20px;
  color: var(--gray-600);
  line-height: 1.7;
}

/* Forms */
.form-card {
  max-width: 420px;
  margin: 0 auto;
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: 48px;
  box-shadow: var(--shadow-xl);
}

.form-card h2 {
  text-align: center;
  margin-bottom: 8px;
}

.form-card-subtitle {
  text-align: center;
  color: var(--gray-600);
  margin-bottom: 32px;
}

.social-buttons {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 12px 20px;
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  background: var(--white);
  font-weight: 500;
  cursor: pointer;
  transition: var(--transition);
}

.social-btn:hover {
  background: var(--gray-50);
  border-color: var(--gray-400);
}

.social-btn svg {
  width: 20px;
  height: 20px;
}

.divider {
  display: flex;
  align-items: center;
  gap: 16px;
  margin: 24px 0;
  color: var(--gray-400);
  font-size: 0.875rem;
}

.divider::before,
.divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--gray-200);
}

.form-group {
  margin-bottom: 16px;
}

.form-group label {
  display: block;
  font-weight: 500;
  margin-bottom: 6px;
  font-size: 0.9rem;
}

.form-group input {
  width: 100%;
  padding: 12px 16px;
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  font-size: 1rem;
  transition: var(--transition);
}

.form-group input:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.1);
}

.form-footer {
  text-align: center;
  font-size: 0.875rem;
  color: var(--gray-600);
  margin-top: 24px;
}

.form-footer a {
  color: var(--primary);
  font-weight: 500;
}

/* Blog Cards */
.blog-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
}

.blog-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--gray-100);
  transition: var(--transition);
}

.blog-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.blog-card-image {
  height: 200px;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400);
}

.blog-card-content {
  padding: 24px;
}

.blog-card-content h4 {
  margin-bottom: 8px;
  transition: var(--transition);
}

.blog-card:hover h4 {
  color: var(--primary);
}

.blog-card-content p {
  color: var(--gray-600);
  font-size: 0.9rem;
}

/* Footer */
.footer {
  background: var(--gray-900);
  color: var(--gray-400);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand {
  max-width: 280px;
}

.footer-brand .nav-logo {
  color: var(--white);
  margin-bottom: 16px;
}

.footer-brand p {
  font-size: 0.9rem;
  line-height: 1.7;
}

.footer-col h4 {
  color: var(--white);
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 20px;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 12px;
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  padding-top: 32px;
  border-top: 1px solid var(--gray-800);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.875rem;
}

.footer-legal {
  display: flex;
  gap: 24px;
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--white);
  border-top: 1px solid var(--gray-200);
  padding: 24px;
  z-index: 2000;
  box-shadow: 0 -4px 20px rgba(0,0,0,0.1);
  display: none;
}

.cookie-banner.show {
  display: block;
}

.cookie-banner-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.cookie-banner p {
  font-size: 0.9rem;
  color: var(--gray-700);
}

.cookie-banner-actions {
  display: flex;
  gap: 12px;
}

/* Modal */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: 3000;
  display: none;
  align-items: center;
  justify-content: center;
}

.modal-overlay.show {
  display: flex;
}

.modal {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: 32px;
  max-width: 500px;
  width: 90%;
  max-height: 90vh;
  overflow-y: auto;
}

.modal h3 {
  margin-bottom: 24px;
}

.modal-close {
  float: right;
  background: none;
  border: none;
  font-size: 1.5rem;
  cursor: pointer;
  color: var(--gray-400);
}

.cookie-category {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
  border-bottom: 1px solid var(--gray-100);
}

.cookie-category-info h4 {
  font-size: 0.95rem;
  margin-bottom: 4px;
}

.cookie-category-info p {
  font-size: 0.8rem;
  color: var(--gray-600);
}

.toggle-checkbox {
  width: 48px;
  height: 26px;
  background: var(--gray-200);
  border-radius: var(--radius-full);
  position: relative;
  cursor: pointer;
  transition: var(--transition);
}

.toggle-checkbox::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 20px;
  height: 20px;
  background: var(--white);
  border-radius: var(--radius-full);
  transition: var(--transition);
}

.toggle-checkbox.active {
  background: var(--primary);
}

.toggle-checkbox.active::after {
  left: 25px;
}

/* Integrations */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}

.integration-item {
  aspect-ratio: 1;
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  transition: var(--transition);
  cursor: pointer;
}

.integration-item:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-md);
}

/* Responsive */
@media (max-width: 1024px) {
  h1 { font-size: 2.5rem; }
  h2 { font-size: 2rem; }

  .use-case-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .pricing-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .pricing-card.featured {
    transform: none;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .hero {
    padding: 120px 0 60px;
  }

  .highlight-feature {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .highlight-feature.reverse {
    direction: ltr;
  }

  .stats-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .pricing-cards {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 16px;
    text-align: center;
  }

  .cookie-banner-inner {
    flex-direction: column;
    text-align: center;
  }

  .blog-grid {
    grid-template-columns: 1fr;
  }
}

